mapper.select:
SELECT
    DISTINCT bcc.part,bct.*
FROM
    biz_course_category bcc
    JOIN biz_course_template bct ON bct.course_category_id = bcc.id
WHERE
    bcc.remove_flag = 0
    AND bct.remove_flag = 0
    AND bcc.category_code = #{condition.categoryCode}

        AND bcc.major = #{condition.major}


        AND bct.part = #{condition.part}


        AND bcc.grade = #{condition.grade}

    ORDER BY bct.course_code ASC
